gFf(){return"\u043f\u0438\u0442\u0430\u043b\u044c\u043d\u0438\u0439 \u0437\u0430\u0439\u043c\u0435\u043d\u043d\u0438\u043a"},
gFd(){return"\u0432\u043a\u0430\u0437\u0456\u0432\u043d\u0438\u0439 \u0437\u0430\u0439\u043c\u0435\u043d\u043d\u0438\u043a"},
gFa(){return"\u0437\u0430\u0439\u043c\u0435\u043d\u043d\u0438\u043a"},
gF1(){return"\u0443\u043c\u043e\u0432\u043d\u0430 \u0447\u0430\u0441\u0442\u043a\u0430"},
