gF3(){return"\u043f\u0438\u0442\u0430\u043b\u044c\u043d\u0430 \u0447\u0430\u0441\u0442\u043a\u0430"},
gF4(){return"\u0437\u0430\u043f\u0435\u0440\u0435\u0447\u043d\u0430 \u0447\u0430\u0441\u0442\u043a\u0430"},
gF0(){return"\u0447\u0430\u0441\u0442\u043a\u0430"},
gES(){return"\u0432\u0438\u0433\u0443\u043a"},
